select date, count(*) games, count(*) filter (where exists (select 1 from pbp_games p where p.id=g.id)) pbp, count(*) filter (where exists (select 1 from shift_charts s where s.game_id=g.id)) shifts, count(*) filter (where exists (select 1 from forge_player_game_strength s where s.game_id=g.id)) derived_player, count(*) filter (where exists (select 1 from "lineCombinations" l where l."gameId"=g.id)) linecombos, count(*) filter (where exists (select 1 from "powerPlayCombinations" l where l."gameId"=g.id)) ppcombos from games g where date between '2026-11-09' and '2026-11-15' group by 1 order by 1
